    GardenProgress = apps.get_model('garden', 'GardenProgress')

    # Old data used four star values. Merge the two highest values into the hard tier.
    SeedType.objects.filter(difficulty__gt=3).update(difficulty=3)

    # Keep the old 3x3 garden positions in the top-left of the fixed 5-wide grid.
    for plot in list(GardenPlot.objects.filter(slot_index__lt=9).only('pk', 'slot_index')):
        GardenPlot.objects.filter(pk=plot.pk).update(slot_index=100 + plot.slot_index)
    for plot in list(GardenPlot.objects.filter(slot_index__gte=100, slot_index__lt=109).only('pk', 'slot_index')):
        old_index = plot.slot_index - 100
        GardenPlot.objects.filter(pk=plot.pk).update(slot_index=(old_index // 3) * 5 + old_index % 3)

    # Plants already fully grown count once toward their difficulty milestone.
    counts_by_user = {}
    for plot in GardenPlot.objects.filter(growth_stage__gte=4, seed_type__isnull=False).select_related('seed_type'):
        tier = max(1, min(3, plot.seed_type.difficulty))
        field = {1: 'easy_completed', 2: 'medium_completed', 3: 'hard_completed'}[tier]
        counts_by_user.setdefault(plot.user_id, {'easy_completed': 0, 'medium_completed': 0, 'hard_completed': 0})[field] += 1
        GardenPlot.objects.filter(pk=plot.pk).update(completion_recorded=True)

    for user_id, counts in counts_by_user.items():
        progress = GardenProgress.objects.create(user_id=user_id, **counts)
        level = 1
        while True:
            required = {1: 0, 2: 0, 3: 0}
            for transition in range(1, level + 1):
                tier = (transition - 1) % 3 + 1
                required[tier] += transition + 2
            actual = {1: progress.easy_completed, 2: progress.medium_completed, 3: progress.hard_completed}
            if all(actual[tier] >= needed for tier, needed in required.items()):
                level += 1
            else:
                break
        progress.level = level
        progress.save(update_fields=['level'])

    # Assign a drip of species unlocks: three of each kind/tier per level.
    for tier in (1, 2, 3):
        for kind in ('tree', 'flower'):
            base = {1: 1, 2: 2, 3: 3}[tier]
            species = list(SeedType.objects.filter(difficulty=tier, kind=kind).order_by('id'))
            for index, plant in enumerate(species):
                SeedType.objects.filter(pk=plant.pk).update(unlock_level=base + index // 3)


